// Asignación de Nivel_De_Dificultad a las preguntas existentes de TODOS los
// servicios de AWS_SERVICES (R1.1). Las preguntas actuales son introductorias
// (definiciones/siglas), por lo que reciben `d: 1` (R7.6). Toda pregunta que ya
// declare un `d` explícito (p. ej. futuras preguntas de nivel 2/3) conserva su
// valor. Esto mantiene la compatibilidad con `q.d || 1` (R1.4) y no altera los
// enunciados ni las opciones existentes (R1.3, R7.5).
for(const serviceId in QUESTIONS){
  for(const question of QUESTIONS[serviceId]){
    if(!Number.isInteger(question.d)) question.d = 1;
  }
}

